const results = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  if (!body || body.event !== 'message') continue;
  const p = body.payload ?? {};
  if (p.is_from_me === true) continue;
  if (p.is_group === true || String(p.chat_id || '').endsWith('@g.us')) continue;

  const chatId = p.chat_id || p.from || '';
  if (!chatId) continue;
  const text = typeof p.body === 'string' ? p.body.trim() : '';
  let audioPath = null;
  if (typeof p.audio === 'string' && p.audio.trim()) audioPath = p.audio.trim();
  else if (p.audio?.path) audioPath = String(p.audio.path).trim();
  const isAudio = Boolean(audioPath);
  const unsupported = !text && !isAudio;
  const inputKind = p.type || (p.image ? 'image' : p.video ? 'vidéo' : p.document ? 'document' : p.sticker ? 'sticker' : 'contenu non reconnu');

  results.push({json:{
    chat_id:chatId, from:p.from || chatId, from_name:p.from_name || '',
    session_id:body.session_id || '', device_jid:body.device_id || '',
    message_id:p.id || p.message_id || '', text, is_audio:isAudio,
    audio_path:audioPath, timestamp:body.timestamp || null,
    unsupported_input:unsupported, input_kind:String(inputKind)
  }});
}
return results;

const source = $('Normaliser message GOWA').first().json;
const corrected = String($json.corrected_text || '').trim();

if (!corrected || corrected === 'TRANSCRIPTION_AMBIGUE') {
  throw new Error('Transcription corrigée non exploitable.');
}

return [{
  json: {
    ...source,
    text: corrected,
    raw_transcription: $json.raw_transcription || '',
    source_type: 'audio'
  }
}];

const source = {...$('Préparer Text-to-SQL').first().json, sql_retry_count:Number($json.sql_retry_count||0)};

let sql = $json?.choices?.[0]?.message?.content;

if (typeof sql !== 'string') {
  return [{
    json: {
      ...source,
      sql_valid: false,
      sql_error: 'Le modèle IA n’a pas retourné une requête SQL exploitable.'
    }
  }];
}

sql = sql.trim()
  .replace(/^```sql\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

if (sql === 'DB_COPILOT_UNSUPPORTED') {
  return [{
    json: {
      ...source,
      sql_valid: false,
      unsupported: true,
      sql_error: 'La question ne peut pas être traitée avec les données métier autorisées.'
    }
  }];
}

// Normalisation défensive de quelques valeurs métier fréquemment mal générées par un LLM.
sql = sql
  .replace(/'payée'/gi, "'PAYÉ'")
  .replace(/'paye'/gi, "'PAYÉ'")
  .replace(/'payé'/gi, "'PAYÉ'")
  .replace(/'en[\s_-]*attente'/gi, "'EN_ATTENTE'")
  .replace(/'annulee?'/gi, "'ANNULÉ'")
  .replace(/'annulé[e]?'/gi, "'ANNULÉ'")
  .replace(/'partiel(le)?'/gi, "'PARTIEL'")
  .replace(/'recu'/gi, "'REÇU'")
  .replace(/'reçu'/gi, "'REÇU'")
  .replace(/'commande'/gi, "'COMMANDE'")
  .replace(/'produit'/gi, "'PRODUIT'")
  .replace(/'service'/gi, "'SERVICE'")
  .replace(/'entree'/gi, "'ENTREE'")
  .replace(/'entrée'/gi, "'ENTREE'")
  .replace(/'sortie'/gi, "'SORTIE'");

const fail = (message) => [{
  json: {
    ...source,
    generated_sql: sql,
    sql_valid: false,
    sql_error: message
  }
}];

if (!/^SELECT\b/i.test(sql))
  return fail('Sécurité : seules les requêtes SELECT sont autorisées.');

if (sql.includes(';'))
  return fail('Sécurité : point-virgule ou instructions multiples interdits.');

if (/--|\/\*|\*\//.test(sql))
  return fail('Sécurité : commentaires SQL interdits.');

if (/\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|COPY|CALL|DO|EXECUTE|MERGE|SET|RESET|VACUUM|ANALYZE|COMMENT|WITH|UNION|INTERSECT|EXCEPT)\b/i.test(sql))
  return fail('Sécurité : opération ou construction SQL non autorisée.');

if (/\b(PG_SLEEP|DBLINK|LO_IMPORT|LO_EXPORT|SET_CONFIG|PG_READ_FILE|PG_LS_DIR|PG_CATALOG|INFORMATION_SCHEMA)\b/i.test(sql))
  return fail('Sécurité : fonction ou schéma système interdit.');

const allowed = new Set([
  'clients',
  'fournisseurs',
  'produits',
  'ventes',
  'vente_lignes',
  'achats',
  'achat_lignes',
  'mouvements_stock',
  'v_stock_produits'
]);

const refs = [];
for (const m of sql.matchAll(/\b(?:FROM|JOIN)\s+((?:"?public"?\.)?"?[a-zA-Z_][a-zA-Z0-9_]*"?)/gi)) {
  let t = m[1].replace(/"/g, '').toLowerCase();
  if (t.startsWith('public.')) t = t.substring(7);
  refs.push(t);
}

if (!refs.length)
  return fail('Sécurité : aucune table métier autorisée détectée.');

for (const t of refs) {
  if (!allowed.has(t))
    return fail(`Sécurité : table non autorisée (${t}).`);
}

// Pas de SELECT imbriqué dans cette version hackathon.
const selectCount = (sql.match(/\bSELECT\b/gi) || []).length;
if (selectCount !== 1)
  return fail('Sécurité : les sous-requêtes ne sont pas autorisées dans cette version.');

const safeSql = `SELECT * FROM (${sql}) AS db_copilot_result LIMIT 200`;

return [{
  json: {
    ...source,
    generated_sql: sql,
    safe_sql: safeSql,
    sql_valid: true,
    unsupported: false
  }
}];

const meta = $('Valider et sécuriser SQL').first().json;
const rawRows = $input.all().map(item => item.json);
const rows = rawRows.filter(r => r && Object.keys(r).length > 0);

return [{
  json: {
    chat_id: meta.chat_id,
    session_id: meta.session_id,
    device_jid: meta.device_jid,
    from_name: meta.from_name,
    question: meta.original_question || meta.text,
    analytical_question: meta.analytical_question || meta.text,
    force_chart: meta.force_chart === true,
    sql: meta.generated_sql,
    rows,
    row_count: rows.length
  }
}];

const SYSTEM_PROMPT = "
Tu es PLUTO DB Copilot WhatsApp, un analyste business senior pour un manager en Guinée.

IMPORTANT JSON
Ta réponse finale doit être UNIQUEMENT un objet JSON valide.
Le mot JSON est volontairement présent ici car l'API utilise response_format=json_object.
Ne retourne aucun texte avant ou après le JSON.
Ne retourne aucun Markdown ni bloc ```json.

ENTRÉES
Tu reçois:
- question: question originale;
- sql: SQL exécuté;
- resultats: tableau JSON PostgreSQL;
- row_count: nombre de lignes;
- force_chart: true si l'utilisateur demande explicitement un graphique.

MISSION
Transformer les données en réponse WhatsApp concise, exacte et utile.

RÈGLES
1. Réponds en français.
2. N'invente jamais une donnée absente des résultats.
3. Ne montre pas le SQL sauf demande explicite.
4. Montants: séparateurs de milliers avec espaces + suffixe GNF.
5. Utilise le gras WhatsApp avec *texte*.
6. Quelques emojis utiles seulement.
7. Pour un KPI simple: 2 à 5 lignes.
8. Pour un classement: présente les principaux résultats.
9. Si row_count=0 ou resultats=[], dis clairement qu'aucune donnée correspondante n'a été trouvée. Ne fabrique rien.
10. Si force_chart=true ET au moins deux valeurs comparables existent, chart DOIT être non-null. C'est une obligation stricte.
11. Si force_chart=true mais qu'il n'existe pas au moins deux valeurs comparables, explique brièvement pourquoi et mets chart=null.
12. Si force_chart=false, mets chart uniquement si cela améliore réellement la compréhension.
13. Série temporelle: line.
14. Comparaison clients/produits/services/villes/fournisseurs: bar.
15. Répartition simple: pie ou doughnut.
16. Maximum 12 points.
17. labels et values doivent avoir la même longueur.
18. values contient uniquement des nombres finis.
19. Ne mets jamais l'URL QuickChart dans message.

FORMAT JSON OBLIGATOIRE SANS GRAPHIQUE
{
  "message": "réponse WhatsApp",
  "chart": null
}

FORMAT JSON OBLIGATOIRE AVEC GRAPHIQUE
{
  "message": "réponse WhatsApp",
  "chart": {
    "type": "bar",
    "title": "Titre court",
    "labels": ["A", "B"],
    "values": [10, 20],
    "dataset_label": "Libellé"
  }
}
";

const input = {
  question: $json.question,
  sql: $json.sql,
  resultats: $json.rows,
  row_count: $json.row_count,
  force_chart: $json.force_chart === true
};

return [{
  json: {
    ...$json,
    synthesis_llm_body: {
      model: 'gpt-4o-mini',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content: SYSTEM_PROMPT
        },
        {
          role: 'user',
          content: 'Réponds uniquement en JSON valide. Données à analyser: ' + JSON.stringify(input)
        }
      ]
    }
  }
}];

const meta = $('Préparer synthèse').first().json;
const raw = $json?.choices?.[0]?.message?.content;

let parsed = null;
try { parsed = JSON.parse(String(raw || '').trim()); }
catch (e) {
  parsed = { message: meta.row_count === 0
      ? '📊 Aucune donnée correspondante n’a été trouvée pour cette demande.'
      : '📊 Les données ont été récupérées, mais je n’ai pas pu formater la réponse. Reformulez votre question si besoin.',
    chart: null };
}

let message = String(parsed?.message || '').trim();
if (!message) {
  message = meta.row_count === 0
    ? '📊 Aucune donnée correspondante n’a été trouvée pour cette demande.'
    : '📊 Analyse terminée.';
}

function quickchart(config){
  return 'https://quickchart.io/chart?width=1000&height=600&format=jpg&backgroundColor=white&devicePixelRatio=1&c=' + encodeURIComponent(JSON.stringify(config));
}

let chartUrl = null;
const chart = parsed?.chart;
if (chart && Array.isArray(chart.labels) && Array.isArray(chart.values)) {
  const labels = chart.labels.slice(0, 12).map(v => String(v));
  const values = chart.values.slice(0, 12).map(Number);
  if (labels.length >= 2 && labels.length === values.length && values.every(Number.isFinite)) {
    const allowedTypes = ['bar','line','pie','doughnut'];
    const type = allowedTypes.includes(chart.type) ? chart.type : 'bar';
    chartUrl = quickchart({ type, data:{ labels, datasets:[{ label: chart.dataset_label || 'Valeur', data: values }] },
      options:{ responsive:true, plugins:{ title:{ display:true, text: chart.title || 'PLUTO DB Copilot' }, legend:{ display:true } } } });
  }
}

// Secours : graphique demandé mais non fourni -> on le construit depuis les lignes
if (!chartUrl && meta.force_chart === true && Array.isArray(meta.rows) && meta.rows.length >= 2) {
  const rows = meta.rows;
  const keys = Object.keys(rows[0] || {});
  const isNum = (v) => v !== null && v !== '' && Number.isFinite(Number(v));
  const valueKey = keys.find(k => rows.some(r => isNum(r[k])) && rows.every(r => r[k] === null || isNum(r[k])));
  const labelKey = keys.find(k => k !== valueKey);
  if (valueKey && labelKey) {
    const labels = rows.slice(0,12).map(r => String(r[labelKey]));
    const values = rows.slice(0,12).map(r => Number(r[valueKey]) || 0);
    chartUrl = quickchart({ type:'bar', data:{ labels, datasets:[{ label: valueKey, data: values }] },
      options:{ responsive:true, plugins:{ title:{ display:true, text:'PLUTO DB Copilot' }, legend:{ display:true } } } });
  }
}

if (meta.force_chart === true && !chartUrl && meta.row_count >= 2) {
  message += '\n\n⚠️ Je n’ai pas pu générer une visualisation fiable avec ces résultats.';
}

return [{ json: {
  chat_id: meta.chat_id, session_id: meta.session_id, device_jid: meta.device_jid,
  message, chart_url: chartUrl, has_chart: !!chartUrl, chart_error: null
} }];

const j = $json;
let message;
if (j.unsupported) {
  message =
    '🤖 *Je n\'ai pas bien compris votre demande.*\n\n' +
    'Pouvez-vous la préciser ? Par exemple :\n' +
    '• « Quels sont mes 5 produits les plus vendus ce mois-ci ? »\n' +
    '• « Quel est le total de mes achats ce mois ? »\n' +
    '• « Quelles factures ne sont pas encore payées ? »\n\n' +
    'Je peux analyser : ventes, clients, produits, stock, fournisseurs, achats et paiements — et faire des *graphiques*.';
} else {
  message =
    '🔒 *Demande non traitée pour raison de sécurité.*\n\n' +
    'Reformulez simplement votre question (ex. « chiffre d\'affaires de ce mois », « top 5 clients »).';
}
return [{ json: { chat_id: j.chat_id, session_id: j.session_id, device_jid: j.device_jid, message } }];

const items = $input.all();

for (const item of items) {
  if (!item.binary?.data) {
    throw new Error('Aucun fichier audio binaire reçu depuis GOWA.');
  }

  item.binary.data.fileName = 'voice.ogg';
  item.binary.data.mimeType = 'audio/ogg';
  item.binary.data.fileExtension = 'ogg';
}

return items;

const src = $('Normaliser message GOWA').first().json;
return [{json:{...src,technical_error:String($json?.error?.message || '').slice(0,900),error_origin:'pipeline audio',message:[
  '🎙️ *Je n’ai pas pu traiter ce vocal.*',
  '',
  'Le fichier peut être incomplet, trop bruité ou le service de transcription peut être momentanément indisponible.',
  'Renvoyez un vocal court et clair, ou écrivez directement votre question. Aucune action n’a été exécutée.'
].join('\n')}}];

const items = $input.all();

for (const item of items) {
  if (!item.binary?.data) {
    throw new Error('Aucune image reçue depuis QuickChart.');
  }

  item.binary.data.fileName = 'db-copilot-chart.jpg';
  item.binary.data.mimeType = 'image/jpeg';
  item.binary.data.fileExtension = 'jpg';
}

return items;

const source = $('Préparer correction transcription').first().json;
let corrected = $json?.choices?.[0]?.message?.content;

corrected = typeof corrected === 'string' ? corrected.trim() : '';

return [{
  json: {
    ...source,
    corrected_text: corrected || 'TRANSCRIPTION_AMBIGUE'
  }
}];

const digits = value => String(value || '').replace(/[^0-9]/g, '');
const manager = digits($env.PLUTO_MANAGER_CHAT_ID || '');
const session = String($env.PLUTO_GOWA_SESSION_ID || '').trim();
const raw = Number($env.PLUTO_SALES_DROP_THRESHOLD || 0.15);
const pct = Math.abs(raw <= 1 ? raw * 100 : raw);
return [{json:{
  SEUIL_BAISSE_PCT:-pct, MANAGER_PHONE:manager, SESSION_ID:session,
  demo_mode:false, supervision_configured:Boolean(manager && session)
}}];

let cfg;
try { const demo = $('Préparer démo contrôlée').first().json; if (demo.demo_mode) cfg = demo; } catch(e) {}
if (!cfg) cfg = $('Paramètres surveillance').first().json;
const r = $json;
const cur = Number(r.ventes_semaine) || 0;
const prev = Number(r.ventes_semaine_prec) || 0;
const variation = prev > 0 ? Math.round(((cur-prev)/prev)*1000)/10 : 0;
const actual = prev > 0 && variation <= cfg.SEUIL_BAISSE_PCT;
return [{json:{...cfg,ventes_semaine:cur,ventes_semaine_prec:prev,
  nb_ventes_semaine:Number(r.nb_ventes_semaine)||0,variation_pct:variation,
  anomalie:Boolean(actual || cfg.demo_mode),actual_anomaly:actual,
  demo_notice:cfg.demo_mode ? 'Simulation contrôlée déclenchée par le manager; les chiffres restent ceux de la base.' : null
}}];

const j = $json;
const SYS = [
'Tu es l\'agent d\'INVESTIGATION de PLUTO DB Copilot (PostgreSQL 16).',
'On te signale une anomalie de ventes. Propose un diagnostic structuré.',
'Retourne UNIQUEMENT du JSON: {"hypotheses":[".."],"requetes":["SELECT .."]}',
'REGLES SQL STRICTES pour chaque requete:',
'- SELECT unique, PAS de point-virgule, PAS de commentaire, PAS de WITH, PAS de UNION.',
'- Uniquement ces tables: clients, fournisseurs, produits, ventes, vente_lignes, achats, achat_lignes, mouvements_stock, v_stock_produits.',
'- Colonnes ventes: id_vente,id_client,date_vente,statut,montant_total_gnf,montant_paye_gnf. Statut: PAYÉ,EN_ATTENTE,ANNULÉ,PARTIEL.',
'- Jointures: vente_lignes.id_vente=ventes.id_vente, vente_lignes.id_produit=produits.id_produit, ventes.id_client=clients.id_client.',
'- v_stock_produits(id_produit,nom,stock_minimum,stock_actuel) pour les ruptures.',
'- Max 3 requetes, chacune ciblant une hypothese (produit, client, statut/annulations, stock/rupture).',
'- Compare 7 derniers jours vs 7 jours precedents avec CASE WHEN sur date_vente.'
].join('\n');
const user = (j.demo_mode ? '[MODE DEMO CONTROLE] ' : '') + 'Signal ventes: variation ' + j.variation_pct + '% (' + j.ventes_semaine + ' vs ' + j.ventes_semaine_prec + ' GNF). Trouve les explications soutenues par les donnees; ne force pas une cause si les preuves sont insuffisantes.';
return [{ json: { ...j, plan_body: { model: 'gpt-4o-mini', temperature: 0,
  response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: SYS }, { role: 'user', content: user } ] } } }];

const base = $('Évaluer seuil').first().json;
let content = $json?.choices?.[0]?.message?.content || '{}';
let parsed; try { parsed = JSON.parse(content); } catch(e){ parsed = {hypotheses:[],requetes:[]}; }
const ALLOWED = new Set(['clients','fournisseurs','produits','ventes','vente_lignes','achats','achat_lignes','mouvements_stock','v_stock_produits']);
function safe(sql){
  if(typeof sql!=='string') return null;
  sql = sql.trim().replace(/^```sql\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim();
  if(!/^SELECT\b/i.test(sql)) return null;
  if(sql.includes(';')) return null;
  if(/--|\/\*|\*\//.test(sql)) return null;
  if(/\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|GRANT|REVOKE|COPY|CALL|DO|EXECUTE|MERGE|SET|RESET|VACUUM|ANALYZE|COMMENT|WITH|UNION|INTERSECT|EXCEPT)\b/i.test(sql)) return null;
  if(/\b(PG_SLEEP|DBLINK|LO_IMPORT|LO_EXPORT|SET_CONFIG|PG_READ_FILE|PG_LS_DIR|PG_CATALOG|INFORMATION_SCHEMA)\b/i.test(sql)) return null;
  for(const m of sql.matchAll(/\b(?:FROM|JOIN)\s+"?([a-zA-Z_][a-zA-Z0-9_]*)"?/gi)){
    if(!ALLOWED.has(m[1].toLowerCase())) return null;
  }
  return sql;
}
const reqs = Array.isArray(parsed.requetes)? parsed.requetes.slice(0,3):[];
const out = [];
reqs.forEach((q,i)=>{ const s=safe(q); if(s) out.push({ json: { ...base, hypotheses: parsed.hypotheses||[], invest_index:i, safe_sql:s } }); });
if(out.length===0){ out.push({ json: { ...base, hypotheses: parsed.hypotheses||[], invest_index:-1, safe_sql: "SELECT 'aucune requete valide' AS info" } }); }
return out;

const items = $input.all();
const base = $('Évaluer seuil').first().json;
const preuves = items.map((it,idx)=>({
  index:idx,
  requete:String(it.json.safe_sql||'').slice(0,300),
  succes:!(it.json?.error || Number(it.json?.statusCode||0)>=400),
  erreur:it.json?.error ? String(it.json.error.message||it.json.error).slice(0,220) : null,
  resultat:it.json
}));
let hypotheses = [];
try { hypotheses = $('Valider SQL invest.').first().json.hypotheses || []; } catch(e) {}
return [{json:{...base,hypotheses,preuves,
  preuves_reussies:preuves.filter(p=>p.succes).length,
  preuves_en_echec:preuves.filter(p=>!p.succes).length,
  technical_error:preuves.some(p=>!p.succes) ? preuves.filter(p=>!p.succes).map(p=>p.erreur).join(' | ').slice(0,900) : null,
  error_origin:'requêtes investigation'
}}];

const base = $('Collecter preuves').first().json;
let exa = [];
let exa_error = null;
try {
  const r = $json || {};
  if (r.error || Number(r.statusCode || 0) >= 400) exa_error = String(r.error?.message || r.message || 'Recherche Exa indisponible');
  const results = r.results || r.data?.results || [];
  exa = results.slice(0,3).map(x=>({titre:x.title,url:x.url,
    extrait:(x.highlights && x.highlights[0]) ? x.highlights[0] : String(x.text||'').slice(0,180)}));
} catch(e) { exa_error = e.message; }
return [{json:{...base,exa_contexte:exa,exa_available:exa.length>0,
  exa_error:exa_error ? String(exa_error).slice(0,200) : null}}];

const j = $json;
const SYS = [
'Tu es PLUTO DB Copilot, agent proactif pour un dirigeant de PME en Guinée.',
'A partir de l\'anomalie, des preuves SQL et du contexte externe (Exa), rends un verdict actionnable.',
'Retourne UNIQUEMENT ce JSON:',
'{"confiance":85,"resume":"1 phrase","cause_probable":"1-2 phrases (base)","contexte_externe":"1 phrase + source ou \\"non déterminant\\"","perte_estimee":"ordre de grandeur en GNF","action_label":"action recommandée courte","message_a_envoyer":"message pro prêt à envoyer (client/fournisseur/équipe)","destinataire_phone":"numéro au format international sans +"}',
'Sépare clairement fait-base, fait-externe et déduction. Si exa_available=false, écris contexte externe indisponible et ne l’invente jamais. En mode demo, annonce explicitement qu’il s’agit d’une simulation contrôlée. Reste concret et bref (WhatsApp).'
].join('\n');
const user = JSON.stringify({ anomalie:{variation_pct:j.variation_pct, ventes_semaine:j.ventes_semaine, ventes_semaine_prec:j.ventes_semaine_prec},
  hypotheses:j.hypotheses, preuves:j.preuves, exa:j.exa_contexte, exa_available:j.exa_available, exa_error:j.exa_error, demo_mode:j.demo_mode, demo_notice:j.demo_notice, manager:j.MANAGER_PHONE });
return [{ json: { ...j, synth_body: { model:'gpt-4o-mini', temperature:0.2,
  response_format:{type:'json_object'},
  messages:[{role:'system',content:SYS},{role:'user',content:user}] } } }];

const base = $('Préparer synthèse + action').first().json;
let v; try { v = JSON.parse($json.choices[0].message.content); } catch(e) { v = {}; }
const digits = value => String(value || '').replace(/[^0-9]/g,'');
const confidence = Math.max(0,Math.min(100,Number(v.confiance||0)));
const minimum = Math.max(0,Math.min(100,Number($env.PLUTO_PROACTIVE_CONFIDENCE_MIN||75)));
const shouldNotify = Boolean(base.demo_mode || confidence >= minimum);
const demoDest = digits($env.PLUTO_DEMO_ACTION_PHONE || base.MANAGER_PHONE);
const proposedDest = digits(v.destinataire_phone || '') || base.MANAGER_PHONE;
const dest = base.demo_mode ? demoDest : proposedDest;
const approvalId = 'PLT-'+Date.now().toString(36).toUpperCase().slice(-7);
const msg = [
  base.demo_mode ? '🧪 *PLUTO DB Copilot — DÉMONSTRATION CONTRÔLÉE*' : '⚠️ *PLUTO DB Copilot — Alerte proactive*',
